window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"GggXTf6RAGU","speaker":"To Lam","role":"President","country":"Viet Nam","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=GggXTf6RAGU","date":"20260922","title":"🇻🇳 Viet Nam - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":777,"words":1815,"counts":{"claims":19,"promises":2,"attacks":0},"topics":[{"topic":"UN reform","share":0.1781,"seconds":138},{"topic":"Cuba","share":0.0991,"seconds":77},{"topic":"Nuclear weapons","share":0.0839,"seconds":65},{"topic":"Digital governance","share":0.0819,"seconds":64},{"topic":"Global economy","share":0.0812,"seconds":63},{"topic":"Vietnam foreign policy","share":0.0808,"seconds":63},{"topic":"Vietnam development","share":0.0805,"seconds":62},{"topic":"East Sea","share":0.0803,"seconds":62},{"topic":"UN charter","share":0.0793,"seconds":62},{"topic":"Multilateral trade","share":0.0779,"seconds":60},{"topic":"UN strengthening","share":0.0772,"seconds":60}],"timeline":[[2,67,"Nuclear weapons"],[68,131,"Global economy"],[132,198,"UN reform"],[199,261,"UN charter"],[262,324,"East Sea"],[326,403,"Cuba"],[404,464,"Multilateral trade"],[465,528,"Digital governance"],[529,601,"UN reform"],[602,665,"Vietnam development"],[665,728,"Vietnam foreign policy"],[729,789,"UN strengthening"]],"stances":{"Nuclear weapons":"To Lam states that the modernization of nuclear weapons and development of new technology weapons are heightening risks of confrontation, miscalculation, conflict, and large-scale wars.","Global economy":"To Lam states that global economic fragmentation, supply chain disruptions, and unchecked competition are creating instability and hindering international cooperation.","UN reform":"To Lam argues that UN institutions require reform to keep pace with current times while fundamental principles must be respected and reinforced.","UN charter":"To Lam asserts that the UN Charter and international law must be fully respected without selectivity to restore trust among nations.","East Sea":"Vietnam is resolute in safeguarding its sovereignty, sovereign rights, and jurisdiction in the East Sea through peaceful means in line with international law.","Cuba":"To Lam calls for the US to end its embargo and sanctions against Cuba and remove Cuba from the list of state sponsors of terrorism.","Multilateral trade":"To Lam argues that the multilateral trading system must be strengthened in an open, equitable, and transparent manner to ensure development opportunities for all countries.","Digital governance":"To Lam argues that technological progress must be inclusive and governed by principles that respect national sovereignty while ensuring developing countries can participate in rule-making.","Vietnam development":"To Lam states that Vietnam is pursuing a new development model focused on productivity and innovation to achieve upper-middle income status by 2030 and high-income status by 2045.","Vietnam foreign policy":"To Lam states that Vietnam pursues a consistent foreign policy of independence and self-reliance while remaining steadfast in upholding the UN charter and international law.","UN strengthening":"To Lam states that Vietnam will work with all countries to strengthen the UN and uphold international law."},"claims":[{"t":51,"quote":"The tendency towards the threat or use of force and the arms race, especially the modernization of nuclear weapons and the development of new technology weapons are heightening the risk of confrontation, miscalculation, conflict, and even of largecale wars.","topic":"Nuclear weapons","kind":"fact"},{"t":69,"quote":"the global economy is becoming increasingly fragmented amid mounting barriers to trade, investment, and technology.","topic":"Global economy","kind":"fact"},{"t":76,"quote":"Supply chain disruptions and economic instability are narrowing development opportunities for many countries.","topic":"Global economy","kind":"fact"},{"t":83,"quote":"Climate change, natural disasters, pandemics and emerging technological risk continue to pose direct threats to the pe lives of the people and their livelihoods and to the development and stability of many nations.","topic":"Global economy","kind":"fact"},{"t":167,"quote":"Over the past eight decades, despite its limitations, the UN has helped sustain dialogue, advance decolonization, uphold the right of peoples to self-determination, and support development.","topic":"UN reform","kind":"fact"},{"t":224,"quote":"The UN charter and international law form the foundation for the international order.","topic":"UN charter","kind":"fact"},{"t":281,"quote":"Vietnam supports the rise of the Palestinian people to self-determination and the two-stage solution with an independent state of Palestine living peacefully alongside the state of Israel in line with international law and relevant UN resolutions in the Asia-Pacific.","topic":"East Sea","kind":"fact"},{"t":296,"quote":"Nearly six decades of the Asan's development have demonstrated that countries can transform suspicion into trust, confrontation into dialogue, division into cooperation, and individual strength into collective might.","topic":"East Sea","kind":"fact"},{"t":338,"quote":"Vietnam has always stood in solidarity with the state and people of Cuba","topic":"Cuba","kind":"fact"},{"t":455,"quote":"Science, technology, digital transformation, and artificial intelligence are opening up unprecedented opportunities. But they're also presenting new challenges.","topic":"Multilateral trade","kind":"fact"},{"t":506,"quote":"Vietnam's hosting of the uh signing ceremony for the UN convention against cyber crime in Hanoi last year reflects our desire to make substantive contributions to global digital cooperation.","topic":"Digital governance","kind":"fact"},{"t":548,"quote":"The strength of the UN does not lie in its ability to replace the responsibilities of state, but in its legitimacy and capacity to build consensus, establish norms, develop rules, and mobilize global efforts to address common challenges for the UN to adapt to the transformations of the time.","topic":"UN reform","kind":"fact"},{"t":586,"quote":"These perspective are drawn from the experience of Vietnam itself over the past half century since it succession to the UN mirrors the transformation of our own country from primarily a recipient of invaluable assistance during the years of DUI.","topic":"UN reform","kind":"self_credit"},{"t":610,"quote":"Vietnamese military personnel and police officers have served and will continue to serve in UN peacekeeping operations carrying our nation's aspiration for peace to places where peace remains fragile.","topic":"Vietnam development","kind":"fact"},{"t":633,"quote":"Looking towards our goal of becoming a developing country with a modern industrial base and upper middle income by 2030 and developed high-income country by 2045.","topic":"Vietnam development","kind":"number"},{"t":677,"quote":"Vietnam will remain steadfast in upholding the UN charter and international law, promoting dialogue on the peaceful settlement of disputes and deepening its participation in UN peacekeeping missions.","topic":"Vietnam foreign policy","kind":"fact"},{"t":688,"quote":"Vietnam is working with fellow ASEAN member states to build a united self-real and resilient ASEAN and actively preparing to host APEC in 2027.","topic":"Vietnam foreign policy","kind":"fact"},{"t":729,"quote":"We will work steadfastly with all countries to strengthen the UN, uphold international law, and translate our shared commitments into tangible benefits for our people.","topic":"UN strengthening","kind":"fact"},{"t":749,"quote":"And on this journey Vietnam will remain an active member, a reliable partner and a responsible nation, always standing ready to contribute to the common endeavors of the international","topic":"UN strengthening","kind":"self_credit"}],"promises":[{"t":729,"quote":"We will work steadfastly with all countries to strengthen the UN, uphold international law, and translate our shared commitments into tangible benefits for our people.","topic":"UN strengthening","kind":"promise"},{"t":749,"quote":"And on this journey Vietnam will remain an active member, a reliable partner and a responsible nation, always standing ready to contribute to the common endeavors of the international","topic":"UN strengthening","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"Nuclear weapons","text":"The assembly will now hear an address by his excellency general secretary of the Communist Party of Vietnam and President of the Social Republic of Vietnam. I request protocol to escort his excellency and to invite him to address the assembly. distinguished guest, ladies and gentlemen, the world is undergoing profound shift in the international order with many risk and uncertainties. The tendency towards the threat or use of force and the arms race, especially the modernization of nuclear weapons and the development of new technology weapons are heightening the risk of confrontation, miscalculation, conflict, and even of largecale wars."},{"t":68,"topic":"Global economy","text":"At the same time, the global economy is becoming increasingly fragmented amid mounting barriers to trade, investment, and technology. Supply chain disruptions and economic instability are narrowing development opportunities for many countries. Climate change, natural disasters, pandemics and emerging technological risk continue to pose direct threats to the pe lives of the people and their livelihoods and to the development and stability of many nations. The shift in the balance of power and development inequalities are placing growing strains on international relations. Instability is further exacerbated when competitions goes unchecked. Commitments are left unfulfilled and international law is applied selectively and erosion of trust is further impeding efforts at cooperation. What should concern us is not only how the international order is changing but where that change will take the world. Change is inevitable for it is part of the objective course of history. However, conflict and confrontation are not inevitable."},{"t":132,"topic":"UN reform","text":"From our own history, Vietnam understands the cost of war, the value of independence, and the power of reconciliation and cooperation. It is therefore my belief that the theme of the session, restoring trust, managing transformation, a UN that delivers for all aptly reflects the urgent demands of the term. Distinguished guest, from the losses of the Second World War, humanity created the UN with the aspiration to prevent wars, safeguard peace, promote cooperation, and place relations among nations on the foundation of common principles. Over the past eight decades, despite its limitations, the UN has helped sustain dialogue, advance decolonization, uphold the right of peoples to self-determination, and support development. This must be preserved and carried forward. Our institutions must be reformed to keep pace with the terms while fundamental principles of the UN charter must be respected and reinforced. What we seek is a more equitable, democratic and inclusive international order where every country has a voice and every nation has the opportunity to develop."},{"t":199,"topic":"UN charter","text":"The mission of our generation is to help shape and manage change so that competition does not turn into confrontation. Differences do not lead to conflict and advances in science and technology do not create new divides. In this spirit, I wish to put forward four key priorities. First, we must restore trust among nations on the basis of respect for the UN charter and international law. The UN charter and international law form the foundation for the international order. They must be respected fully, consistently, and without selectivity. All states must respect one each other's independence, sovereignty, territorial integrity, and right to choose their own path of development, refrain from interference in internal affairs, and refrain from the threat or use a force inconsistent with the UN charter. Restoring trust does not require countries to erase differences, but rather to manage such differences responsibly. Crisis must be prevented, competition must be kept under control, and dialogue must be sustained."},{"t":262,"topic":"East Sea","text":"Major powers should lead by example in respecting international law, exercising restraint and responsibly addressing common challenges and the UN must remain at the heart of these efforts. In every conflict, civilians must be protected. International humanitarian law must be respected and humanitarian access must be ensured. Vietnam supports the rise of the Palestinian people to self-determination and the two-stage solution with an independent state of Palestine living peacefully alongside the state of Israel in line with international law and relevant UN resolutions in the Asia-Pacific. Nearly six decades of the Asan's development have demonstrated that countries can transform suspicion into trust, confrontation into dialogue, division into cooperation, and individual strength into collective might. In that spirit, Vietnam remains steadfast in its commitment to resolving disputes, including those in the East Sea. By peaceful means in line with international law, particularly the 1982 ANC clause, Vietnam is resolute in safeguarding it sovereignty, sovereign rights, and jurisdiction."},{"t":326,"topic":"Cuba","text":"The seas and oceans must remain spaces of peace, cooperation, connectivity, and sustainable development. In this same spirit of peace and respect for people's rights to development, Vietnam has always stood in solidarity with the state and people of Cuba, we call upon the US to end the unilateral embargo and in sanctions and the energy blocket against Cuba and remove Cuba from the list of state sponsors of terrorism. We also call upon the international community to support Cuba in overcoming the sanction induced crisis. Second, we must advance development that is equitable, humane, and inclusive and sustainable. International commitments must be translated into action and bring people lives of peace, security, dignity, and happiness. It is for this reason that the pact for the future and the 2030 agenda. Our promises to present and future generations must be implemented earnestly and in full. Commitments on financing for development, including the Sevilla commitment, must be translated into concrete measures expanding access to long-term financing at affordable cost, supporting countries burdened by debt, and amplifying the voice of developing countries in international financial and monetary institutions."},{"t":404,"topic":"Multilateral trade","text":"The multilateral trading system must be strengthened in an open, equitable, and transparent manner, ensuring development opportunities for all countries. Climate action must be accorded its rightful place in development cooperation particularly via adaptation finance technology transfer and a just energy transition. Development must be people centered and leave no one behind. Growth must go handinhand with social progress and equity environmental protection and the safeguarding of people's livelihoods especially for vulnerable countries and communities. Global progress must uphold the spirit of humanity in relations among nations. Safeguard their legitimate interests and respect differences in history, culture and development conditions. Third, we must proactively shape technology governance so that progress serves humanity and our common development. Science, technology, digital transformation, and artificial intelligence are opening up unprecedented opportunities. But they're also presenting new challenges."},{"t":465,"topic":"Digital governance","text":"The future of technology does not automatically guarantee equitability and technological progress must help narrow divides and expand development opportunities rather than creating new forms of dependency on new sources of conflict. We need to develop inclusive, safe, transparent and accountable principles and governance frameworks to ensure that technologies will be in service of the people while respecting national sovereignty, digital sovereignty and the right to development. Developing countries must be able to participate substantively in rule making, receive support for infrastructure and digital capacity and enjoy equitable access to the benefits of scientific and technological progress. Vietnam's hosting of the uh signing ceremony for the UN convention against cyber crime in Hanoi last year reflects our desire to make substantive contributions to global digital cooperation. Vietnam stands ready to work with partners to strengthen cooperation and build capacity in preventing and combating cyber crime so that people may leave safely and benefit from technological progress."},{"t":529,"topic":"UN reform","text":"We also stand ready to support international initiatives on green and digital transformation and the development of effective governance framework so that science and technology can truly become drivers of shared development. Fourth, we must strengthen multilateralism and the essential indispensable role of the UN. The strength of the UN does not lie in its ability to replace the responsibilities of state, but in its legitimacy and capacity to build consensus, establish norms, develop rules, and mobilize global efforts to address common challenges for the UN to adapt to the transformations of the time. Vietnam supports efforts to reform the organization, particularly the GA, the security council and the secretariat with a view to enhance effectiveness, prioritizing structural reform and streamlining the apparatus while fully harnessing the UN's advantage in advancing global agendas and safeguarding the interests of developing These perspective are drawn from the experience of Vietnam itself over the past half century since it succession to the UN mirrors the transformation of our own country from primarily a recipient of invaluable assistance during the years of DUI."},{"t":602,"topic":"Vietnam development","text":"Vietnam today is making proactive contributions to our common endeavors while deepening and broadening our substantive relations with the UN. Vietnamese military personnel and police officers have served and will continue to serve in UN peacekeeping operations carrying our nation's aspiration for peace to places where peace remains fragile. Our tradition for of independence and several lands provides a foundation for Vietnam to strengthen its strategic autonomy and proactively pursue international integration. Looking towards our goal of becoming a developing country with a modern industrial base and upper middle income by 2030 and developed high-income country by 2045. Vietnam is establishing a new development model based on productivity, quality, and added value with science, technology, innovation, and digital transformation as key drivers with economic growth closely linked to cultural development, social progress, and equity, and environmental protection. Autonomy also means proactively adapting and cooperating with the world on an equal footing."},{"t":665,"topic":"Vietnam foreign policy","text":"Vietnam therefore pursues a consistent foreign policy of independence, autonomy, self-reliance, peace, friendship, cooperation and development, and of multilateralization and diversification of external relations. Vietnam will remain steadfast in upholding the UN charter and international law, promoting dialogue on the peaceful settlement of disputes and deepening its participation in UN peacekeeping missions. Vietnam is working with fellow ASEAN member states to build a united self-real and resilient ASEAN and actively preparing to host APEC in 2027. And as a member of the UN Human Rights Council, Vietnam champions dialogue and cooperation in promoting and protecting human rights and in ensuring that all can share the fruits of development. We stand ready to share our experience in poverty reduction, agricultural development and climate change adaptation to work with partners to broaden cooperation for common interest. The world will continue to change. The direction for such change will depend on the choices we make and the responsibilities we shoulder today. Vietnam chooses peace, cooperation, and development."},{"t":729,"topic":"UN strengthening","text":"We will work steadfastly with all countries to strengthen the UN, uphold international law, and translate our shared commitments into tangible benefits for our people. We believe that with a strong UN together we can build a more peaceful, equitable, inclusive and better world for all. And on this journey Vietnam will remain an active member, a reliable partner and a responsible nation, always standing ready to contribute to the common endeavors of the international Thank you very much. &gt;&gt; On behalf of the assembly, I wish to thank the general secretary of the Communist Party of Vietnam and the president of the Social Republic of We shall now continue the general"}],"compare":[{"topic":"UN & its reform","share":0.3346,"mean":0.2041,"rank":35,"others":170},{"topic":"Cuba","share":0.0991,"mean":0.0109,"rank":8,"others":23},{"topic":"Nuclear Weapons","share":0.0839,"mean":0.002,"rank":2,"others":6},{"topic":"Digital Governance","share":0.0819,"mean":0.0029,"rank":3,"others":7},{"topic":"Global Economy","share":0.0812,"mean":0.0142,"rank":13,"others":31},{"topic":"East China Sea","share":0.0803,"mean":0.0,"rank":1,"others":0},{"topic":"Global Trade","share":0.0779,"mean":0.0044,"rank":6,"others":7}]};
